// Title: Apply a 150% zoom to Excel worksheets before converting to PDF using Aspose.Cells for .NET
// Common Searches: how to set worksheet zoom level in Aspose.Cells before PDF export C# | increase Excel sheet size in PDF generated by Aspose.Cells .NET | scale PDF output of an Excel workbook using Aspose.Cells page setup zoom | Aspose.Cells C# convert workbook to PDF with a custom scaling factor | apply custom zoom to all worksheets when saving as PDF with Aspose.Cells
// Tags: worksheet page setup zoom Aspose.Cells | pdf export scaling Aspose.Cells | custom zoom factor before pdf save C# | adjust excel sheet size in pdf output | set page setup zoom for pdf conversion

using System;
using System.IO;
using Aspose.Cells;

// The example checks for the source Excel file, loads it into a Workbook, sets each worksheet's PageSetup.Zoom to 150% to enlarge the content, creates default PdfSaveOptions, and saves the workbook as a PDF while handling any runtime errors.
class Program
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";
            const string outputPath = "output.pdf";

            // Ensure the input file exists to prevent FileNotFoundException
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Input file not found: {inputPath}");
                return;
            }

            // Load the workbook containing the data
            Workbook workbook = new Workbook(inputPath);

            // Apply a 150% zoom to all worksheets (acts as scaling for PDF output)
            foreach (Worksheet sheet in workbook.Worksheets)
            {
                sheet.PageSetup.Zoom = 150; // 150% of original size
            }

            // Configure PDF save options (default options are sufficient here)
            PdfSaveOptions pdfOptions = new PdfSaveOptions();

            // Save the workbook as PDF using the configured options
            workbook.Save(outputPath, pdfOptions);
            Console.WriteLine($"PDF saved successfully to {outputPath}");
        }
        catch (Exception ex)
        {
            // Handle any runtime errors gracefully
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
